	_, err := o.Raw(query, args...).Values(&maps)
	if err != nil {
		return nil, err
	}

	results := make([]map[string]interface{}, len(maps))
	for i, m := range maps {
		results[i] = map[string]interface{}(m)
	}
	return results, nil
}

